-- 126: Original BrillaPrep WASSCE Islamic Religious Studies syllabus evidence beta questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_021', 'topic_was_irs_5', 'subj_wassce_irs', 'exam_wassce', 'When is tayammum permitted?', 'multiple_choice', '["A. When water is unavailable or its use would cause genuine harm","B. Whenever a person wishes to avoid all preparation","C. Only after completing the prayer","D. When clean water is freely available and safe"]', 'A', 'Tayammum is a lawful dry purification using clean earth under recognised necessity; it is not a convenience that replaces usable water without cause. Therefore the correct answer is A: When water is unavailable or its use would cause genuine harm.', 'hard', 1, 1, 90, 'st_was_irs_5', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_022', 'topic_was_irs_5', 'subj_wassce_irs', 'exam_wassce', 'Which prayer is performed in congregation on Friday in place of the normal midday prayer for those obligated to attend?', 'multiple_choice', '["A. Tahajjud","B. Jumu’ah","C. Witr","D. Janazah"]', 'B', 'Jumu’ah includes a sermon and congregational prayer and has special communal significance in weekly Muslim worship. Therefore the correct answer is B: Jumu’ah.', 'easy', 2, 2, 90, 'st_was_irs_5', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_023', 'topic_was_irs_5', 'subj_wassce_irs', 'exam_wassce', 'What is the purpose of wudu before prayer?', 'multiple_choice', '["A. A substitute for every ethical duty","B. A guarantee that no mistake can occur","C. Ritual purification and readiness for worship","D. A method of calculating Zakah"]', 'C', 'Wudu uses prescribed washing to prepare for prayer, joining physical cleanliness with conscious spiritual readiness. Therefore the correct answer is C: Ritual purification and readiness for worship.', 'medium', 1, 1, 90, 'st_was_irs_5', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_024', 'topic_was_irs_5', 'subj_wassce_irs', 'exam_wassce', 'During which month is the obligatory fast observed?', 'multiple_choice', '["A. Muharram only","B. Rabi al-Awwal","C. Dhu al-Qadah","D. Ramadan"]', 'D', 'Fasting Ramadan is a pillar of Islam and trains self-restraint, gratitude, devotion and awareness of people in need. Therefore the correct answer is D: Ramadan.', 'hard', 2, 2, 90, 'st_was_irs_5', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_025', 'topic_was_irs_5', 'subj_wassce_irs', 'exam_wassce', 'What is the qiblah?', 'multiple_choice', '["A. The direction of the Ka’bah faced during prayer","B. The sermon delivered after every meal","C. The charity due on crops","D. The chain of a Hadith"]', 'A', 'Facing the qiblah unifies worshippers in direction while prayer remains directed to Allah rather than to the building itself. Therefore the correct answer is A: The direction of the Ka’bah faced during prayer.', 'easy', 3, 3, 90, 'st_was_irs_5', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_026', 'topic_was_irs_6', 'subj_wassce_irs', 'exam_wassce', 'Which two primary sources form the foundation of Shari’ah?', 'multiple_choice', '["A. Local rumour and personal desire","B. The Qur’an and Sunnah","C. Trade records and poetry alone","D. Astronomy and architecture"]', 'B', 'Islamic law begins with the Qur’an and authenticated Prophetic Sunnah, with disciplined methods used for matters requiring further interpretation. Therefore the correct answer is B: The Qur’an and Sunnah.', 'medium', 2, 2, 90, 'st_was_irs_6', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_027', 'topic_was_irs_6', 'subj_wassce_irs', 'exam_wassce', 'What is ijma in Islamic legal reasoning?', 'multiple_choice', '["A. A private dream treated as public law","B. Any custom even when it contradicts revelation","C. Qualified scholarly consensus on a matter","D. A commercial partnership deed"]', 'C', 'Ijma refers to recognised consensus among qualified scholars and is treated within legal theory as a source after the foundational texts. Therefore the correct answer is C: Qualified scholarly consensus on a matter.', 'hard', 1, 1, 90, 'st_was_irs_6', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_028', 'topic_was_irs_6', 'subj_wassce_irs', 'exam_wassce', 'What is qiyas in Islamic legal reasoning?', 'multiple_choice', '["A. Replacing revelation with personal preference","B. Memorising a chapter without understanding","C. Cancelling every earlier judgment","D. Reasoning by analogy from an established ruling and its effective cause"]', 'D', 'Qiyas applies a known rule to a new case that shares the relevant underlying cause, using disciplined rather than arbitrary comparison. Therefore the correct answer is D: Reasoning by analogy from an established ruling and its effective cause.', 'easy', 2, 2, 90, 'st_was_irs_6', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_029', 'topic_was_irs_6', 'subj_wassce_irs', 'exam_wassce', 'What should guide custody decisions concerning a child after family separation?', 'multiple_choice', '["A. The child’s welfare within applicable Islamic and lawful responsibilities","B. Using the child to punish the other parent","C. Ignoring care, safety and development","D. Awarding custody solely by wealth"]', 'A', 'Al-hadanah concerns care and upbringing. Responsible decisions protect the child’s welfare and rights rather than treating custody as retaliation. Therefore the correct answer is A: The child’s welfare within applicable Islamic and lawful responsibilities.', 'medium', 1, 1, 90, 'st_was_irs_6', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_030', 'topic_was_irs_6', 'subj_wassce_irs', 'exam_wassce', 'Why is a marriage contract important in Islam?', 'multiple_choice', '["A. It removes the need for free consent","B. It establishes a lawful union with recognised mutual rights and responsibilities","C. It permits concealment of agreed obligations","D. It makes kindness between spouses optional"]', 'B', 'Nikah is a serious covenant requiring consent and defined responsibilities, including dignity, support and fair treatment within the marriage. Therefore the correct answer is B: It establishes a lawful union with recognised mutual rights and responsibilities.', 'hard', 3, 3, 90, 'st_was_irs_6', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.', 'https://www.waeconline.org.ng/e-learning/Islamic/IRKmain.html', 0, 1 FROM questions WHERE id BETWEEN 'q_was_irs_b001_021' AND 'q_was_irs_b001_030';
